#!/usr/bin/env node
// context-budget.mjs: estimate the start-up context each subagent pays before its task message.
// Per the docs a subagent receives its file body (system prompt), the CLAUDE.md hierarchy, git
// status, and the full content of every skill listed in `skills:`. This script sums what it can
// measure from the repo: agent body + preloaded SKILL.md files + CLAUDE.md with its @imports.
// Tokens are estimated as characters / 4 (a rough rule of thumb, not a tokenizer).
// Usage (from AI-SDLC-frappe/): node workflows/composition/context-budget.mjs [project-dir]   (default .)
import { readFileSync, readdirSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";

const est = (chars) => Math.round(chars / 4);

/** CLAUDE.md plus @imports (one level, outside code spans), as loaded for every agent. */
export function claudeMdChars(projectDir) {
  const p = join(projectDir, "CLAUDE.md");
  if (!existsSync(p)) return 0;
  const text = readFileSync(p, "utf8");
  let total = text.length;
  for (const line of text.split("\n")) {
    for (const m of line.replace(/`[^`]*`/g, "").matchAll(/(?:^|\s)@([\w./-]+)/g)) {
      const imp = join(dirname(p), m[1]);
      if (existsSync(imp)) total += readFileSync(imp, "utf8").length;
    }
  }
  return total;
}

export function agentBudget(projectDir, file) {
  const text = readFileSync(file, "utf8");
  const m = text.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
  const front = m ? m[1] : "";
  const body = m ? m[2] : text;
  const name = (front.match(/^name:\s*(.+)$/m) || [])[1]?.trim() || file;
  const skills = [];
  const inline = front.match(/^skills:[ \t]*(\S.*)$/m);
  if (inline) skills.push(...inline[1].replace(/[[\]]/g, "").split(",").map((s) => s.trim()).filter(Boolean));
  else {
    const block = front.match(/^skills:[ \t]*\n((?:[ \t]+-[ \t]+.+\n?)+)/m);
    if (block) skills.push(...block[1].split("\n").map((l) => l.replace(/^\s+-\s+/, "").trim()).filter(Boolean));
  }
  let skillChars = 0;
  const missing = [];
  for (const s of skills) {
    const sp = join(projectDir, ".claude", "skills", s, "SKILL.md");
    if (existsSync(sp)) skillChars += readFileSync(sp, "utf8").length; else missing.push(s);
  }
  return { name, bodyChars: body.length, skills, skillChars, missing };
}

export function report(projectDir) {
  const dir = join(projectDir, ".claude", "agents");
  const shared = claudeMdChars(projectDir);
  const rows = readdirSync(dir).filter((n) => n.endsWith(".md")).sort().map((n) => agentBudget(projectDir, join(dir, n)));
  return { shared, rows: rows.map((r) => ({ ...r, totalTokens: est(shared + r.bodyChars + r.skillChars) })) };
}

if (process.argv[1] && new URL(import.meta.url).pathname === (await import("node:path")).resolve(process.argv[1])) {
  const projectDir = process.argv[2] || ".";
  const { shared, rows } = report(projectDir);
  console.log(`CLAUDE.md + imports (every agent): ~${est(shared)} tokens`);
  console.log(["agent".padEnd(14), "body".padStart(6), "skills".padStart(7), "total".padStart(7), "  preloaded skills"].join(""));
  for (const r of rows) {
    console.log([r.name.padEnd(14), String(est(r.bodyChars)).padStart(6), String(est(r.skillChars)).padStart(7), String(r.totalTokens).padStart(7),
      "  " + (r.skills.join(", ") || "-") + (r.missing.length ? `  (missing: ${r.missing.join(", ")})` : "")].join(""));
  }
}

#!/usr/bin/env node
// security-scope.mjs: decide from a diff whether the security step of a workflow is mandatory.
//
// Course rule (workflows/feature-delivery.md, "Conditional branch"): the security agent MUST run
// when a change to spice_lite touches any of
//   1. a DocType permissions array (or a field permlevel) in **/doctype/*/*.json
//   2. a whitelisted method: a changed line with @frappe.whitelist / allow_guest, or any change
//      under spice_lite/api/ (where the whitelisted FHIR-lite endpoints live)
//   3. hooks.py (doc_events, fixtures, permission_query_conditions, has_permission, overrides)
//   4. ignore_permissions
// plus two extras that bypass permissions just as quietly:
//   5. an added frappe.db.sql( / frappe.get_all( / frappe.qb. / frappe.db.count( outside tests
//   6. fixtures that ship permission records (Role, DocPerm, Custom DocPerm, User Permission, Role Profile)
// Anything else -> the step may be skipped, and the skip is recorded with the changed paths.
//
// Usage:
//   node workflows/composition/security-scope.mjs <change.patch>            classify a patch file
//   node workflows/composition/security-scope.mjs --git [--base HEAD] [path] classify the working tree
//        (tracked changes against <base> plus untracked files; path defaults to sample-app)
//   add --json for machine-readable output.
// Exit 0 = classified (MANDATORY or SKIP), 2 = usage or git error.
import { readFileSync, existsSync } from "node:fs";
import { execFileSync } from "node:child_process";
import { resolve } from "node:path";

const DOCPERM_KEY = /^\s*"(role|if_owner|read|write|create|delete|submit|cancel|amend|report|export|import|share|print|email|select|permlevel|permissions)"\s*:/;
const PERM_FIXTURE = /"doctype"\s*:\s*"(Role|DocPerm|Custom DocPerm|User Permission|Role Profile)"/;
const BYPASS = /frappe\.db\.sql\(|frappe\.get_all\(|frappe\.qb\.|frappe\.db\.count\(/;
const isTest = (p) => /(^|\/)tests?\//.test(p) || /(^|\/)test_[^/]*\.py$/.test(p);

/** Parse a unified diff into [{ path, added: [{line, text}], removed: [{line, text}] }]. */
export function parseDiff(text) {
  const files = [];
  let cur = null, newLine = 0, oldLine = 0;
  for (const raw of String(text).split(/\r?\n/)) {
    let m;
    if ((m = raw.match(/^diff --git a\/(\S+) b\/(\S+)/))) { cur = { path: m[2], added: [], removed: [] }; files.push(cur); continue; }
    if ((m = raw.match(/^\+\+\+ (?:b\/)?(\S+)/))) {
      if (m[1] === "/dev/null") continue;
      if (!cur || cur.path !== m[1]) { cur = { path: m[1], added: [], removed: [] }; files.push(cur); }
      continue;
    }
    if (/^--- /.test(raw)) {
      if (!cur) { const o = raw.match(/^--- (?:a\/)?(\S+)/); cur = { path: o ? o[1] : "?", added: [], removed: [] }; files.push(cur); }
      continue;
    }
    if ((m = raw.match(/^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@/))) { oldLine = Number(m[1]); newLine = Number(m[2]); continue; }
    if (!cur) continue;
    if (raw.startsWith("+")) cur.added.push({ line: newLine++, text: raw.slice(1) });
    else if (raw.startsWith("-")) cur.removed.push({ line: oldLine++, text: raw.slice(1) });
    else if (raw.startsWith(" ")) { newLine++; oldLine++; }
  }
  return files;
}

/** Classify parsed files. Returns { mandatory, reasons: [{rule, location, evidence}], paths }. */
export function classify(files) {
  const reasons = [];
  const add = (rule, path, l, why) => reasons.push({ rule, location: `${path}:${l.line}`, evidence: l.text.trim().slice(0, 120), why });
  for (const f of files) {
    const changed = [...f.added.map((l) => ({ ...l, side: "+" })), ...f.removed.map((l) => ({ ...l, side: "-" }))];
    if (/(^|\/)hooks\.py$/.test(f.path) && changed.length) {
      add(3, f.path, changed[0], "hooks.py changed (doc_events, fixtures, permission hooks and overrides live here)");
    }
    if (/\/doctype\/[^/]+\/[^/]+\.json$/.test(f.path)) {
      const hit = changed.find((l) => DOCPERM_KEY.test(l.text));
      if (hit) add(1, f.path, hit, "DocType permissions array or permlevel changed");
    }
    if (/(^|\/)fixtures\/[^/]+\.json$/.test(f.path)) {
      const hit = changed.find((l) => PERM_FIXTURE.test(l.text));
      if (hit) add(6, f.path, hit, "fixture ships permission records (imported with force on every migrate)");
    }
    if (/(^|\/)(common_)?site_config\.json$/.test(f.path)) add(6, f.path, changed[0] || { line: 0, text: "" }, "site config (secrets) changed");
    if (!f.path.endsWith(".py") || isTest(f.path)) continue;
    const wl = changed.find((l) => /frappe\.whitelist|allow_guest/.test(l.text));
    if (wl) add(2, f.path, wl, "whitelisted method added or changed");
    else if (/(^|\/)api\/[^/]+\.py$/.test(f.path) && changed.length) add(2, f.path, changed[0], "spice_lite/api/ changed (whitelisted endpoints)");
    const ip = changed.find((l) => /ignore_permissions/.test(l.text));
    if (ip) add(4, f.path, ip, "ignore_permissions added or removed");
    const by = f.added.find((l) => BYPASS.test(l.text));
    if (by) add(5, f.path, by, "permission-bypassing query added (db.sql, get_all, qb or db.count)");
  }
  reasons.sort((a, b) => a.location.localeCompare(b.location, "en", { numeric: true }));
  return { mandatory: reasons.length > 0, reasons, paths: files.map((f) => f.path).sort() };
}

/** Diff of the working tree against base (tracked) plus untracked files as all-added. */
export function gitDiff(cwd, base = "HEAD", path = "sample-app") {
  const run = (args) => execFileSync("git", args, { cwd, encoding: "utf8", maxBuffer: 64 * 1024 * 1024 });
  let text = run(["diff", "--no-color", "--relative", base, "--", path]);
  const untracked = run(["ls-files", "--others", "--exclude-standard", "--", path]).split("\n").filter(Boolean);
  for (const u of untracked) {
    const p = resolve(cwd, u);
    if (!existsSync(p)) continue;
    const lines = readFileSync(p, "utf8").split("\n");
    if (lines.at(-1) === "") lines.pop();
    text += `diff --git a/${u} b/${u}\nnew file mode 100644\n--- /dev/null\n+++ b/${u}\n@@ -0,0 +1,${lines.length} @@\n` + lines.map((l) => "+" + l).join("\n") + "\n";
  }
  return text;
}

export function format(result) {
  if (!result.mandatory) {
    return `SECURITY STEP: SKIP (no security trigger in ${result.paths.length} changed file(s): ${result.paths.join(", ") || "none"})`;
  }
  const rules = [...new Set(result.reasons.map((r) => r.rule))].sort().join(", ");
  return [`SECURITY STEP: MANDATORY (rules ${rules})`, ...result.reasons.map((r) => `- rule ${r.rule} ${r.location}: ${r.why} | ${r.evidence}`)].join("\n");
}

const isMain = process.argv[1] && resolve(process.argv[1]) === resolve(new URL(import.meta.url).pathname);
if (isMain) {
  const args = process.argv.slice(2);
  const json = args.includes("--json");
  const rest = args.filter((a) => a !== "--json");
  let text;
  try {
    if (rest[0] === "--git") {
      let base = "HEAD";
      const bi = rest.indexOf("--base");
      if (bi > 0) { base = rest[bi + 1]; rest.splice(bi, 2); }
      text = gitDiff(process.cwd(), base, rest[1] || "sample-app");
    } else if (rest[0] && existsSync(rest[0])) {
      text = readFileSync(rest[0], "utf8");
    } else {
      console.error("usage: security-scope.mjs <change.patch> | --git [--base REV] [path]  [--json]");
      process.exit(2);
    }
  } catch (e) {
    console.error(`security-scope: ${e.message}`);
    process.exit(2);
  }
  const result = classify(parseDiff(text));
  console.log(json ? JSON.stringify(result, null, 2) : format(result));
}

#!/usr/bin/env node
// check-roster-flat.mjs: lint .claude/agents/*.md for the course's delegation topology.
//   - roster agents (architect, developer, reviewer, tester, security, sre) must not be able to
//     spawn subagents: `tools` must be present and must not contain Agent/Task, unless
//     `disallowedTools` removes Agent. An omitted `tools` inherits every tool, including Agent.
//   - a parenthesised Agent(...) list in a non-orchestrator agent is flagged: Claude Code ignores
//     the list in subagent definitions, so it restricts nothing.
//   - the orchestrator must list Agent(...) with roster agents only, and no Edit/Bash.
// Usage (from AI-SDLC-frappe/): node workflows/composition/check-roster-flat.mjs [agents-dir]   (default .claude/agents)
// Complements agents/check-agents.mjs (module 05, per-agent contract conformance): this file checks the
// delegation topology only, so it can run on any agents directory, including a scratch copy.
// Exit 0 = topology OK, 1 = at least one error.
import { readFileSync, readdirSync, existsSync } from "node:fs";
import { join } from "node:path";

export const ROSTER = ["architect", "developer", "reviewer", "tester", "security", "sre"];

/** Minimal frontmatter reader for `name`, `tools`, `disallowedTools` (string or YAML list). */
export function readAgent(text) {
  const m = text.match(/^---\r?\n([\s\S]*?)\r?\n---/);
  if (!m) return null;
  const out = {};
  const lines = m[1].split(/\r?\n/);
  for (let i = 0; i < lines.length; i++) {
    const kv = lines[i].match(/^([A-Za-z]+):\s*(.*)$/);
    if (!kv || !["name", "tools", "disallowedTools"].includes(kv[1])) continue;
    if (kv[2].trim()) { out[kv[1]] = kv[2].trim(); continue; }
    const items = [];
    while (i + 1 < lines.length && /^\s+-\s+/.test(lines[i + 1])) items.push(lines[++i].replace(/^\s+-\s+/, "").trim());
    out[kv[1]] = items.join(", ");
  }
  return out;
}

/** Split "Agent(a, b), Read, Bash(git diff *)" on top-level commas. */
export function splitTools(s) {
  if (s == null) return null;
  const parts = [];
  let depth = 0, cur = "";
  for (const ch of String(s).replace(/^["']|["']$/g, "")) {
    if (ch === "(") depth++;
    if (ch === ")") depth--;
    if (ch === "," && depth === 0) { parts.push(cur.trim()); cur = ""; } else cur += ch;
  }
  if (cur.trim()) parts.push(cur.trim());
  return parts;
}

const isAgentTool = (t) => /^(Agent|Task)(\(|$)/.test(t);

export function lint(agents) {
  const errors = [], warnings = [];
  for (const { file, fm } of agents) {
    if (!fm || !fm.name) { errors.push(`${file}: no frontmatter name`); continue; }
    const tools = splitTools(fm.tools);
    const denied = splitTools(fm.disallowedTools) || [];
    const agentDenied = denied.some((t) => /^(Agent|Task)$/.test(t));
    if (fm.name === "orchestrator") {
      const a = (tools || []).find(isAgentTool);
      if (!a || !a.includes("(")) errors.push(`${file}: orchestrator must list Agent(<roster types>) in tools`);
      else {
        const types = a.slice(a.indexOf("(") + 1, a.lastIndexOf(")")).split(",").map((x) => x.trim()).filter(Boolean);
        const bad = types.filter((t) => !ROSTER.includes(t));
        if (bad.length) errors.push(`${file}: orchestrator may only delegate to roster agents, found ${bad.join(", ")}`);
      }
      for (const t of tools || []) if (/^(Edit|Bash|NotebookEdit)(\(|$)/.test(t)) errors.push(`${file}: orchestrator must not have ${t}`);
      continue;
    }
    if (tools === null && !agentDenied) {
      errors.push(`${file}: "${fm.name}" omits tools, so it inherits every tool including Agent; list tools explicitly or add disallowedTools: Agent`);
      continue;
    }
    const agentTool = (tools || []).find(isAgentTool);
    if (agentTool && agentTool.includes("(")) warnings.push(`${file}: "${agentTool}" in a subagent definition: the type list is ignored (only claude --agent main threads honour it)`);
    if (agentTool && !agentDenied) {
      const msg = `${file}: "${fm.name}" can spawn subagents (${agentTool})`;
      if (ROSTER.includes(fm.name)) errors.push(`${msg}; roster agents stay at depth 1, remove Agent from tools`);
      else warnings.push(`${msg}; nested delegation, check CLAUDE_CODE_MAX_SUBAGENT_SPAWN_DEPTH`);
    }
  }
  return { errors, warnings };
}

export function loadAgents(dir) {
  return readdirSync(dir).filter((n) => n.endsWith(".md")).sort()
    .map((n) => ({ file: join(dir, n), fm: readAgent(readFileSync(join(dir, n), "utf8")) }));
}

if (process.argv[1] && new URL(import.meta.url).pathname === (await import("node:path")).resolve(process.argv[1])) {
  const dir = process.argv[2] || ".claude/agents";
  if (!existsSync(dir)) { console.error(`no such directory: ${dir}`); process.exit(1); }
  const agents = loadAgents(dir);
  const { errors, warnings } = lint(agents);
  for (const a of agents) {
    const t = splitTools(a.fm && a.fm.tools);
    console.log(`${(a.fm && a.fm.name) || a.file}`.padEnd(14) + (t ? t.join(", ") : "(tools omitted: inherits all)"));
  }
  for (const w of warnings) console.log(`WARN  ${w}`);
  for (const e of errors) console.log(`ERROR ${e}`);
  console.log(errors.length ? `\n${errors.length} error(s)` : `\nOK  roster is flat: only the orchestrator delegates (${agents.length} agent files)`);
  process.exit(errors.length ? 1 : 0);
}

#!/usr/bin/env node
// Tests for check-roster-flat.mjs, context-budget.mjs and security-scope.mjs (Frappe edition).
// Usage (from AI-SDLC-frappe/): node workflows/composition/composition.test.mjs
import { spawnSync } from "node:child_process";
import { mkdtempSync, mkdirSync, writeFileSync, rmSync, readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { lint, readAgent, splitTools } from "./check-roster-flat.mjs";
import { report } from "./context-budget.mjs";
import { classify, parseDiff } from "./security-scope.mjs";

const here = dirname(fileURLToPath(import.meta.url));
const fixture = (name) => readFileSync(join(here, "fixtures", name), "utf8");
const example = (name) => readFileSync(join(here, "..", "examples", "feature-observation-code-vocabulary", "patches", name), "utf8");
const agent = (name, tools, extra = "") => ({ file: `${name}.md`, fm: readAgent(`---\nname: ${name}\ndescription: test\n${tools === null ? "" : `tools: ${tools}\n`}${extra}---\nbody\n`) });
const rules = (text) => [...new Set(classify(parseDiff(text)).reasons.map((r) => r.rule))].sort().join(",");
const newFile = (path, lines) => `diff --git a/${path} b/${path}\nnew file mode 100644\n--- /dev/null\n+++ b/${path}\n@@ -0,0 +1,${lines.length} @@\n${lines.map((l) => "+" + l).join("\n")}\n`;

const cases = [
  // ---- topology lint -------------------------------------------------------------------
  ["splitTools keeps the Agent(...) list together",
    () => JSON.stringify(splitTools("Agent(architect, developer), Read, Bash(git diff *)")) === JSON.stringify(["Agent(architect, developer)", "Read", "Bash(git diff *)"])],
  ["YAML list form of tools is read",
    () => readAgent("---\nname: tester\ntools:\n  - Read\n  - Grep\n---\n").tools === "Read, Grep"],
  ["flat roster + orchestrator passes",
    () => lint([agent("orchestrator", "Agent(architect, developer, reviewer, tester, security, sre), Read, Write, Grep, Glob, Skill"), agent("reviewer", "Read, Grep, Glob, Bash"), agent("security", "Read, Grep, Glob")]).errors.length === 0],
  ["roster agent listing Agent is an error",
    () => lint([agent("architect", "Read, Grep, Glob, Agent")]).errors.some((e) => /can spawn subagents/.test(e))],
  ["roster agent that omits tools inherits Agent: error",
    () => lint([agent("developer", null)]).errors.some((e) => /inherits every tool including Agent/.test(e))],
  ["omitted tools but disallowedTools: Agent is accepted",
    () => lint([agent("developer", null, "disallowedTools: Agent\n")]).errors.length === 0],
  ["Agent(type) list in a subagent definition raises the 'ignored' warning",
    () => lint([agent("sre", "Read, Agent(Explore)")]).warnings.some((w) => /type list is ignored/.test(w))],
  ["orchestrator delegating to a non-roster type is an error",
    () => lint([agent("orchestrator", "Agent(architect, general-purpose), Read")]).errors.some((e) => /general-purpose/.test(e))],
  ["orchestrator with Bash is an error (it must never run bench)",
    () => lint([agent("orchestrator", "Agent(architect), Read, Bash")]).errors.some((e) => /must not have Bash/.test(e))],
  ["CLI lint of the real .claude/agents exits 0",
    () => spawnSync(process.execPath, [join(here, "check-roster-flat.mjs"), join(here, "..", "..", ".claude", "agents")], { encoding: "utf8" }).status === 0],
  // ---- context budget ------------------------------------------------------------------
  ["context budget counts body, preloaded skill and CLAUDE.md import", () => {
    const p = mkdtempSync(join(tmpdir(), "budget-"));
    try {
      mkdirSync(join(p, ".claude", "agents"), { recursive: true });
      mkdirSync(join(p, ".claude", "skills", "code-review"), { recursive: true });
      mkdirSync(join(p, "context"), { recursive: true });
      writeFileSync(join(p, "CLAUDE.md"), "rules\n- @context/a.md\n");          // 22 chars
      writeFileSync(join(p, "context", "a.md"), "x".repeat(378));              // 378 chars
      writeFileSync(join(p, ".claude", "skills", "code-review", "SKILL.md"), "y".repeat(800));
      writeFileSync(join(p, ".claude", "agents", "reviewer.md"), "---\nname: reviewer\nskills:\n  - code-review\n---\n" + "z".repeat(400));
      const r = report(p).rows[0];
      return r.name === "reviewer" && r.skillChars === 800 && r.bodyChars === 400 && r.totalTokens === Math.round((22 + 378 + 800 + 400) / 4);
    } finally { rmSync(p, { recursive: true, force: true }); }
  }],
  // ---- security scope (conditional security step) --------------------------------------
  ["whitelist-count.patch is MANDATORY (rule 2 whitelist, rule 5 frappe.db.count)",
    () => rules(fixture("whitelist-count.patch")) === "2,5"],
  ["encounter-refactor.patch (controller only) is SKIP",
    () => classify(parseDiff(fixture("encounter-refactor.patch"))).mandatory === false],
  ["tests-only patch is SKIP (test files are excluded from rules 2, 4 and 5)",
